INSERT INTO `common_tools` VALUES ('0f28dcdb-9896-44c5-8f99-bbdae04c11fd','全屏专注计时器','双模式切换：支持“倒计时（Timer）”和“正计时（Stopwatch）”。\r\n沉浸式体验：支持全屏模式，隐藏多余元素，专注于时间。\r\n零依赖音效：使用浏览器原生 AudioContext 生成“嘀嘀”报警声，无需加载 mp3 文件。\r\n智能交互：支持快捷加时（+1分, +5分），倒计时结束自动红色闪烁警示。\r\n视觉防抖：使用等宽数字字体设置，防止倒计时过程中数字左右跳动。','0a349ea8-1158-43d9-b5e4-c5e971a753a6','html','document-text','common_tools/html/842c434c/index.html',0,1,'2026-01-12 17:25:02','2026-01-12 17:25:02'),('17ca37e5-c28d-4de4-b067-fb21b162b18f','高效催交助手','名单核对黑名单-高效催交助手','0a349ea8-1158-43d9-b5e4-c5e971a753a6','html','wrench','common_tools/html/e772c7be/index.html',1,1,'2026-01-23 13:30:00','2026-01-23 13:30:00'),('1b5225ba-0d48-45cd-8c06-436238cbd6f7','二维码生成器','实时预览：输入文本或调整配置时，右侧二维码实时更新（带防抖处理）。\r\n高度定制：支持自定义前景色、背景色、边距以及纠错等级（L/M/Q/H）。\r\n高清下载：直接生成并下载 PNG 图片，文件名自动包含时间戳。\r\n容错处理：当输入内容过长超出版本限制时，自动提示错误而非崩溃。','e51e7a71-f43a-4e1b-8f28-0ace65901413','html','document-text','common_tools/html/a2c55315/index.html',0,1,'2026-01-12 17:53:30','2026-01-12 17:53:30'),('38171715-5e8d-4d46-a1d1-43f7bb38792d','文本对比','多模式对比：支持“字符级”、“单词级”和“行级”三种精度的对比。','doc-tools','html','document-text','common_tools/html/7b48313b/index.html',0,1,'2026-01-12 17:10:15','2026-01-12 17:10:15'),('4137c58f-3b15-4bb8-93e7-c44dd0167d8d','古诗词雅致排版工具','古诗词排版与导出工具。为了实现“所见即所得”的排版和图片导出功能。','0a349ea8-1158-43d9-b5e4-c5e971a753a6','html','photo','common_tools/html/0418acb6/index.html',0,1,'2026-01-12 17:48:27','2026-01-12 17:48:27'),('730694bb-2771-4d14-9009-46a854459767','成绩分段统计','智能解析：支持从 Excel、Word 直接复制粘贴，自动识别逗号、空格、换行符作为分隔符。\r\n核心指标看板：实时计算平均分、中位数、最高/最低分、及格率、优秀率。\r\n分段直方图：自动生成 5 个标准分数段（90-100, 80-89...）的分布图，直观显示成绩分布形态。\r\n异常值检测：自动标记满分或零分的特殊情况。','0a349ea8-1158-43d9-b5e4-c5e971a753a6','html','clipboard-document','common_tools/html/6eb85d5c/index.html',0,1,'2026-01-12 17:43:37','2026-01-12 17:43:37'),('79c39aa1-640e-4bc9-bf41-b0e56fe07132','字数统计','混合语言统计：智能区分中文字符（按字算）和英文单词（按词算）。\r\n多维度数据：同时显示总字符数、不含空格字符数、词数、段落数、行数。\r\n阅读预估：根据平均阅读速度计算预计阅读时间。\r\n沉浸式输入：大尺寸输入框，自动保存内容，刷新不丢失。','doc-tools','html','circle-stack','common_tools/html/8ac6d78d/index.html',0,1,'2026-01-12 17:18:10','2026-01-12 17:18:10'),('c68e734a-00c0-4182-a277-04b82726bc91','图片裁剪工具','专业级裁剪体验：集成 Cropper.js，支持自由比例、固定比例（1:1, 4:3, 16:9 等）裁剪。\r\n全功能工具栏：提供旋转（±90°）、缩放、翻转（水平/垂直）、重置等操作。\r\n精准尺寸控制：\r\n实时显示当前裁剪区域的像素尺寸。\r\n支持手动输入目标导出尺寸（宽/高），并提供“锁定纵横比”功能，确保图片不变形。\r\n高清导出：基于 Canvas 生成高质量图片，支持下载为 PNG 格式。','e51e7a71-f43a-4e1b-8f28-0ace65901413','html','photo','common_tools/html/9186f8fe/index.html',0,1,'2026-01-12 18:03:29','2026-01-12 18:03:29'),('d2a958e4-1c94-46e9-a712-7f20578424df','JSON格式化','JSON 智能格式化工具','e51e7a71-f43a-4e1b-8f28-0ace65901413','html','cpu-chip','common_tools/html/43c53472/index.html',0,1,'2026-01-12 16:04:28','2026-01-12 16:04:28'),('d430740b-e683-4c60-852c-2a99e062b9eb','随机分组工具','双模式分组：\r\n指定组数：例如“把30人分成5组”（每组人数自动计算，余数均匀分配）。\r\n指定每组人数：例如“每组4人”（组数自动计算，最后余下的人单独一组或并入最后一组）。\r\n智能分配算法：使用 Fisher-Yates 洗牌算法确保绝对随机，公平无规律。\r\n可视化结果：结果以卡片矩阵形式展示，清晰明了。\r\n快捷操作：支持一键复制所有分组结果（格式化文本），方便直接粘贴到微信/文档。','0a349ea8-1158-43d9-b5e4-c5e971a753a6','html','document-text','common_tools/html/45eeb248/index.html',0,1,'2026-01-12 17:38:47','2026-01-12 17:38:47'),('f016c699-0cfd-4ba5-8e5f-95c6a9460485','随机点名','沉浸式大屏：极简主界面，超大字体显示名字，适合投影仪。\r\n\r\n动态滚轮特效：点击开始后，名字会快速滚动（类似老虎机），增加悬念。\r\n\r\n智能名单管理：\r\n支持一键导入/粘贴大量名单。\r\n“去重模式”：点过的学生自动暂时移除，确保每个人都被点到（直到重置）。\r\n自动保存名单到 localStorage。\r\n公平记录：底部自动记录当次“中奖”名单历史。','0a349ea8-1158-43d9-b5e4-c5e971a753a6','html','cpu-chip','common_tools/html/9b4f2a39/index.html',0,1,'2026-01-12 17:30:03','2026-01-12 17:30:03'),('markdown-editor','Markdown编辑器','在线编辑Markdown文档，实时预览，支持导出Word/PDF','doc-tools','built_in','document-text',NULL,1,1,'2026-01-11 23:55:21','2026-01-11 23:55:21');
/*!40000 ALTER TABLE `common_tools` ENABLE KEYS */;
