  `created_at` datetime NOT NULL,
  `media_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '多模态内容JSON字符串（图片、音频、视频等）',
  `model_provider` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AI服务提供商',
  `model_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用的模型名称',
  `prompt_tokens` int DEFAULT NULL COMMENT '用户消息的token消耗',
  `completion_tokens` int DEFAULT NULL COMMENT 'AI回复的token消耗',
  `total_tokens` int DEFAULT NULL COMMENT '本条消息的总token消耗',
  PRIMARY KEY (`message_id`),
  KEY `idx_session_id` (`session_id`),
