--
-- Table structure for table `token_usage_logs`
--

DROP TABLE IF EXISTS `token_usage_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `token_usage_logs` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户ID',
  `session_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话ID',
  `message_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息ID',
  `model_provider` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'AI服务提供商',
  `model_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型名称',
  `prompt_tokens` int NOT NULL COMMENT 'Prompt token数',
  `completion_tokens` int NOT NULL COMMENT 'Completion token数',
  `total_tokens` int NOT NULL COMMENT '总token数',
  `created_at` datetime NOT NULL DEFAULT (now()) COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_token_logs_user_date` (`user_id`,`created_at`),
  KEY `idx_token_logs_session` (`session_id`),
  KEY `idx_token_logs_message` (`message_id`),
  KEY `idx_token_logs_provider` (`model_provider`),
  CONSTRAINT `token_usage_logs_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `token_usage_logs_ibfk_2` FOREIGN KEY (`session_id`) REFERENCES `sessions` (`session_id`) ON DELETE CASCADE,
  CONSTRAINT `token_usage_logs_ibfk_3` FOREIGN KEY (`message_id`) REFERENCES `messages` (`message_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Token使用日志表，用于计费和审计';
/*!40101 SET character_set_client = @saved_cs_client */;

--
