LOCK TABLES `token_usage_logs` WRITE;
/*!40000 ALTER TABLE `token_usage_logs` DISABLE KEYS */;
/*!40000 ALTER TABLE `token_usage_logs` ENABLE KEYS */;
UNLOCK TABLES;

